llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Lycopene, a large highly lipophilic polyisoprenoid hydrocarbon with no ionizable groups, showed 24.5% ± 6% oral bioavailability for cis isomers in healthy subjects, providing direct evidence that extreme lipophilicity does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Etretinate, despite extremely low aqueous solubility, has approximately 40% oral bioavailability in humans, demonstrating that poor solubility alone is not affirmative evidence for F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Hyperforin, a polyprenylated lipophilic natural product, exhibits high oral bioavailability after oral dosing, supporting transfer of moderate-to-good absorption to the query's prenylated quinone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "The lipophilic nabumetone active metabolite reached 38% absolute bioavailability in healthy subjects, reinforcing that lipophilic molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All transferable experimental evidence points to F ≥ 20%: lipophilic, poorly soluble molecules such as lycopene, etretinate, and hyperforin show moderate oral bioavailability, overriding the physicochemical prior. No affirmative experimental evidence supports F < 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact ubiquinone/polyprenyl quinone scaffold.",
    "Closest analogues are smaller or have different head groups; cis/trans isomerism and formulation effects may alter transferability.",
    "First-pass metabolism and lymphatic absorption for the query are uncharacterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

